from pathlib import Path
p=Path('app/src/main/assets/fake_world/overrides/wechat-chat-actions.js')
text=p.read_text(encoding='utf-8')
old="""    const makeTransferBubble = message => {\n      const line=document.createElement('div');line.className='fw-chat-message fw-chat-message--outgoing fw-chat-message--transfer';const card=document.createElement('div');card.className='fw-transfer-chat-card';const icon=document.createElement('span');icon.className='fw-transfer-chat-card__icon';icon.innerHTML='<img src=\"./assets/wechat-transfer-card-icon.png\" alt=\"\" aria-hidden=\"true\">';const content=document.createElement('div');content.className='fw-transfer-chat-card__content';const amount=document.createElement('strong');amount.textContent='¥'+Number(message.amount||0).toFixed(2);const desc=document.createElement('span');desc.textContent=String(message.note||'').trim()||'你发起了一笔转账';content.append(amount,desc);card.append(icon,content);const footer=document.createElement('div');footer.className='fw-transfer-chat-card__footer';footer.textContent='转账';card.appendChild(footer);line.appendChild(card);const img=document.createElement('img');img.className='fw-chat-message__avatar';img.alt=getSelfName();img.dataset.fwSelfAvatar='1';img.dataset.fwAvatarValue=getSelfAvatar();img.src=fallbackSelfAvatar;resolveSelfAvatar(getSelfAvatarValue()).then(src=>{if(src&&img.isConnected)img.src=src});line.appendChild(img);messages.appendChild(line);\n    };\n"""
new="""    const makeTransferBubble = message => {\n      const line=document.createElement('div');\n      line.className='fw-chat-message fw-chat-message--outgoing fw-chat-message--transfer';\n      const card=document.createElement('div');\n      card.className='fw-transfer-chat-card';\n      const artwork=document.createElement('img');\n      artwork.className='fw-transfer-chat-card__artwork';\n      artwork.src='./assets/wechat-transfer-card-bg.png';\n      artwork.alt=''; artwork.draggable=false; artwork.setAttribute('aria-hidden','true');\n      const content=document.createElement('div'); content.className='fw-transfer-chat-card__content';\n      const amount=document.createElement('strong'); amount.textContent='¥'+Number(message.amount||0).toFixed(2);\n      const desc=document.createElement('span'); desc.textContent=String(message.note||'').trim()||'你发起了一笔转账';\n      content.append(amount,desc);\n      const footer=document.createElement('div'); footer.className='fw-transfer-chat-card__footer'; footer.textContent='转账';\n      card.append(artwork,content,footer); line.appendChild(card);\n      const img=document.createElement('img'); img.className='fw-chat-message__avatar'; img.alt=getSelfName(); img.dataset.fwSelfAvatar='1'; img.dataset.fwAvatarValue=getSelfAvatar(); img.src=fallbackSelfAvatar;\n      resolveSelfAvatar(getSelfAvatarValue()).then(src=>{if(src&&img.isConnected)img.src=src}); line.appendChild(img); messages.appendChild(line);\n    };\n"""
if old not in text:
    raise SystemExit('old transfer block not found')
p.write_text(text.replace(old,new),encoding='utf-8')
print('patched js transfer bubble')
